1	package api
2	
3	import (
4		"encoding/json"
5		"errors"
6		"io"
7		"net/http"
8		"net/url"
9		"strings"
10	
11		"github.com/gin-gonic/gin"
12	
13		"github.com/xjeey8iust/sen-incident-response-flow/internal/store"
14	)
15	
16	var validSeverities = map[string]bool{
17		"low":      true,
18		"medium":   true,
19		"high":     true,
20		"critical": true,
21	}
22	
23	var validStages = map[string]bool{
24		"受理": true,
25		"遏制": true,
26		"清除": true,
27		"恢复": true,
28		"关闭": true,
29	}
30	
31	// NewRouter wires the public HTTP surface. The service contract in README.md
32	// describes the error shape every entry must keep.
33	func NewRouter(st *store.Store) *gin.Engine {
34		gin.SetMode(gin.ReleaseMode)
35		router := gin.New()
36		router.Use(gin.Recovery())
37	
38		router.GET("/healthz", func(c *gin.Context) {
39			if err := st.Ping(); err != nil {
40				writeError(c, http.StatusServiceUnavailable, "storage_unavailable", "database is not available")
41				return
42			}
43			c.JSON(http.StatusOK, gin.H{"status": "ok", "database": "ok"})
44		})
45	
46		router.POST("/incidents", createIncident(st))
47		router.GET("/incidents", queryIncidents(st))
48	
49		router.NoRoute(func(c *gin.Context) {
50			writeError(c, http.StatusNotFound, "route_not_found", "no route matches this path")
51		})
52		return router
53	}
54	
55	// registerRequest mirrors the accepted registration body. Pointer fields let
56	// the handler reject missing keys and explicit nulls alike.
57	type registerRequest struct {
58		ID       *string   `json:"id"`
59		Severity *string   `json:"severity"`
60		Assets   *[]string `json:"assets"`
61		Owner    *string   `json:"owner"`
62	}
63	
64	func createIncident(st *store.Store) gin.HandlerFunc {
65		return func(c *gin.Context) {
66			var payload registerRequest
67			decoder := json.NewDecoder(c.Request.Body)
68			decoder.DisallowUnknownFields()
69			if err := decoder.Decode(&payload); err != nil {
70				writeInvalidRequest(c)
71				return
72			}
73			if err := decoder.Decode(&struct{}{}); err != io.EOF {
74				writeInvalidRequest(c)
75				return
76			}
77			if !payload.valid() {
78				writeInvalidRequest(c)
79				return
80			}
81	
82			incident, err := st.Register(*payload.ID, *payload.Severity, *payload.Owner, *payload.Assets)
83			if errors.Is(err, store.ErrIncidentConflict) {
84				writeError(c, http.StatusConflict, "incident_conflict", "incident id is already registered with different attributes")
85				return
86			}
87			if err != nil {
88				writeError(c, http.StatusServiceUnavailable, "storage_unavailable", "database is not available")
89				return
90			}
91			c.JSON(http.StatusCreated, incident)
92		}
93	}
94	
95	// valid reports whether every required field is present and well formed.
96	func (r *registerRequest) valid() bool {
97		if r.ID == nil || strings.TrimSpace(*r.ID) == "" {
98			return false
99		}
100		if r.Severity == nil || !validSeverities[*r.Severity] {
101			return false
102		}
103		if r.Owner == nil || strings.TrimSpace(*r.Owner) == "" {
104			return false
105		}
106		if r.Assets == nil || len(*r.Assets) == 0 {
107			return false
108		}
109		for _, asset := range *r.Assets {
110			if strings.TrimSpace(asset) == "" {
111				return false
112			}
113		}
114		return true
115	}
116	
117	func queryIncidents(st *store.Store) gin.HandlerFunc {
118		return func(c *gin.Context) {
119			// Parse the raw query ourselves: URL.Query() silently drops segments
120			// with broken percent-escapes or unescaped semicolons, which would
121			// turn a malformed filter into an unconditional listing. Any parse
122			// error rejects the whole request before the store is touched.
123			query, err := url.ParseQuery(c.Request.URL.RawQuery)
124			if err != nil {
125				writeInvalidQuery(c)
126				return
127			}
128			for key, values := range query {
129				if key != "severity" && key != "stage" && key != "id" {
130					writeInvalidQuery(c)
131					return
132				}
133				if len(values) != 1 || values[0] == "" {
134					writeInvalidQuery(c)
135					return
136				}
137			}
138	
139			if id := query.Get("id"); id != "" {
140				if len(query) != 1 {
141					writeInvalidQuery(c)
142					return
143				}
144				incident, err := st.Get(id)
145				if errors.Is(err, store.ErrIncidentNotFound) {
146					writeError(c, http.StatusNotFound, "incident_not_found", "no incident is registered with this id")
147					return
148				}
149				if err != nil {
150					writeError(c, http.StatusServiceUnavailable, "storage_unavailable", "database is not available")
151					return
152				}
153				c.JSON(http.StatusOK, incident)
154				return
155			}
156	
157			severity := query.Get("severity")
158			if severity != "" && !validSeverities[severity] {
159				writeInvalidQuery(c)
160				return
161			}
162			stage := query.Get("stage")
163			if stage != "" && !validStages[stage] {
164				writeInvalidQuery(c)
165				return
166			}
167	
168			incidents, err := st.List(severity, stage)
169			if err != nil {
