339	
340	func TestQueryRejectsMalformedQueryString(t *testing.T) {
341		server, _ := newTestRouter(t)
342		registerIncident(t, server.URL, "INC-1", "medium", "alice")
343	
344		cases := []string{
345			"?severity=%ZZ",                 // broken escape in value
346			"?%ZZ=high",                     // broken escape in name
347			"?severity=%2",                  // truncated escape
348			"?severity=%",                   // lone percent
349			"?id=INC-1&stage=%ZZ",           // valid id must not rescue a bad segment
350			"?stage=%ZZ&id=INC-1",           // segment order is irrelevant
351			"?severity=medium&stage=%ZZ",    // valid filter plus bad segment
352			"?foo=%ZZ",                      // bad escape on an unknown parameter
353			"?severity=%ZZ&severity=medium", // bad escape on a repeated parameter
354			"?id=INC-1;severity=medium",     // unescaped semicolon between segments
355			"?severity=medium;",             // trailing semicolon
356		}
357		for _, query := range cases {
358			t.Run(query, func(t *testing.T) {
359				status, body := doRequest(t, http.MethodGet, server.URL+"/incidents"+query, "")
360				if status != http.StatusBadRequest {
361					t.Fatalf("status = %d, want 400 (body %v)", status, body)
362				}
363				if len(body) != 1 {
364					t.Fatalf("error response must hold only the top-level error object: %v", body)
365				}
366				if code := errorCode(t, body); code != "invalid_query" {
